files.code:
.toolbar {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  height: 160px;
}

.toolbar .save {
  align-self: stretch;
}

files.codeZh:
.toolbar {
  display: flex;
  /* 主轴变成纵向 */
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  height: 160px;
}

.toolbar .save {
  /* 这一个被拉伸到满高 */
  align-self: stretch;
}

files.code:
.header {
  position: relative;
  z-index: 1;
}

.hero {
  position: relative;
  z-index: 2;
}

.dropdown {
  position: absolute;
  top: 100%;
  z-index: 10;
}

files.codeZh:
.header {
  position: relative;
  /* 这里形成了层叠上下文 */
  z-index: 1;
}

.hero {
  position: relative;
  z-index: 2;
}

.dropdown {
  position: absolute;
  top: 100%;
  /* 10 只在 header 内部有效 */
  z-index: 10;
}

.container {
  /* 固定宽度，比手机视口宽 3 倍 */
  width: 1200px;
}

.plan {
  width: 360px;
}

.btn {
  background: blue;
  color: white;
}

/* 两个类，优先级更高 */
.panel .btn {
  background: #ddd;
}

files.code:
.card {
  height: 200px;
  /* overflow is left at its default: visible */
}

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.card {
  min-width: 240px;
}

files.codeZh:
.grid {
  display: grid;
  /* 固定四列，不会换行 */
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.card {
  min-width: 240px;
}

html { font-size: 16px; }

.panel {
  /* 相对父级 */
  font-size: 1.2em;
}

.card {
  font-size: 1.2em;
}

.card .title {
  /* 相对 .card，又会再乘一次 */
  font-size: 1.2em;
}

.page {
  /* 这个祖先成了滚动容器 */
  overflow: hidden;
}

.section-header {
  position: sticky;
  top: 0;
}

